import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = "Dawid Gwizdz, Marcin Usielski"
__copyright__ = "Copyright (C) 2019-2024, Nokia"
__email__ = "dawid.gwizdz@nokia.com, marcin.usielski@nokia.com"


class Status(GenericRtg):
    """Status command class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Status command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Status, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.re_fail = re.compile(r"Invalid command")
        self.header = ""
        self.number = ""

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "status"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_header(line)
                self._parse_scenario(line)
                self._parse_execution_param(line)
            except ParsingDone:
                pass
        return super(Status, self).on_new_line(line, is_full_line)

    # Example line: Execution errors:
    _re_header = re.compile(r"Execution\s*(?P<HEADER>.*):")

    def _parse_header(self, line):
        """
        Parse line contains executions list header.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_header, line):
            self.current_ret[self._regex_helper.group("HEADER")] = {}
            self.header = self._regex_helper.group("HEADER")
            raise ParsingDone

    # Example line: 111. start attach
    _re_scenario = re.compile(r"^(?P<NUMBER>\d+).\s+start\s+(?P<SCENARIO>\w+)")

    def _parse_scenario(self, line):
        """
        Parse line contains scenario.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_scenario, line):
            self.number = self._regex_helper.group("NUMBER")
            self.current_ret[self.header][self.number] = {}
            self.current_ret[self.header][self.number]["scenario"] = self._regex_helper.group("SCENARIO")
            raise ParsingDone

    # Example line:      started : 20190715-091508
    _re_execution_param = re.compile(r"^\s+(?P<KEY>qued|started|finished|duration|errored|error)\s*:\s+(?P<VALUE>.*)")

    def _parse_execution_param(self, line):
        """
        Parse line contains execution parameter.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(self._re_execution_param, line):
            self.current_ret[self.header][self.number][self._regex_helper.group("KEY")] = self._regex_helper.group("VALUE")
            raise ParsingDone


